-- progression-v5: safe incremental migration, also appended to fresh initialization.
-- Never writes character progression, existing per-level curves, pet species caps,
-- exp_accum, or exp_total. Missing source rows are restored verbatim from seed.
CREATE TABLE IF NOT EXISTS game_progression_versions (
 version TEXT PRIMARY KEY, player_cap INT NOT NULL, pet_cap INT NOT NULL,
 player_checksum TEXT NOT NULL, pet_checksum TEXT NOT NULL,
 reward_version TEXT NOT NULL, installed_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
DO $$ BEGIN
 IF EXISTS(SELECT FROM game_trial_rules WHERE id=1 AND max_level NOT IN (60,100)) THEN
  RAISE EXCEPTION 'unexpected trial max_level; manual progression review required';
 END IF;
 IF EXISTS(SELECT FROM characters WHERE level<1 OR level>100 OR exp<0) THEN
  RAISE EXCEPTION 'invalid legacy character progression; diagnose without rewriting saves';
 END IF;
END $$;
ON CONFLICT(level) DO NOTHING;
ON CONFLICT(row_no) DO NOTHING;
DO $$ BEGIN
 IF (SELECT count(*) FROM game_levels WHERE level BETWEEN 1 AND 100)<>100 OR
    (SELECT encode(sha256(convert_to(string_agg(level::text||':'||exp::text||E'\n','' ORDER BY level),'UTF8')),'hex') FROM game_levels WHERE level BETWEEN 1 AND 100)<>'4d768109ae6d3d4852c14580dee319766ecec9138b7d4c244a50fe48d3f4fe0a' THEN
  RAISE EXCEPTION 'player curve differs from approved seed; no tuned rows overwritten';
 END IF;
 IF (SELECT count(*) FROM gamedata.ov_petlevelexp WHERE level BETWEEN 1 AND 80)<>80 OR
    (SELECT encode(sha256(convert_to(string_agg(level::text||':'||exp_need::text||E'\n','' ORDER BY level),'UTF8')),'hex') FROM gamedata.ov_petlevelexp WHERE level BETWEEN 1 AND 80)<>'f68e9dc5a171d6491614a101ff28af1896339c668d987a94f1410578fca6317a' THEN
  RAISE EXCEPTION 'pet curve differs from approved seed; no tuned rows overwritten';
 END IF;
END $$;
-- Preserve existing 12–63 balance; extend the exact seed stat model through 103.
 SELECT m.id,l, greatest(1,m.hp::bigint*l/10), round(l*2*type_atk*identity*0.8), round(l*2*type_atk*identity*1.2),
 round(l*2*type_matk*identity), l, floor(l*0.4), l*3, is_boss, CASE WHEN m.combat_type='法系' THEN 'caster' ELSE 'melee' END
 FROM game_monsters m
 CROSS JOIN generate_series(64,103) l
 CROSS JOIN LATERAL (SELECT m.id IN (3147,3148,3154,3155,3161,3162,3168,3169,3175,3176) AS is_boss,
 CASE WHEN m.id IN (3147,3148,3154,3155,3161,3162,3168,3169,3175,3176) THEN 2.0 ELSE 1.0 END AS identity,
 CASE m.combat_type WHEN '重型' THEN 0.75 WHEN '器物' THEN 0.75 WHEN '法系' THEN 0.5 WHEN '刺客' THEN 1.4 ELSE 1.0 END AS type_atk,
 CASE m.combat_type WHEN '重型' THEN 0.75 WHEN '器物' THEN 0.75 WHEN '法系' THEN 1.6 WHEN '刺客' THEN 0.5 ELSE 1.0 END AS type_matk) rates
 WHERE m.id BETWEEN 3142 AND 3176
 ON CONFLICT(monster_id,level) DO NOTHING;
DO $$ BEGIN
 IF (SELECT count(*) FROM game_trial_monster_stats WHERE monster_id BETWEEN 3142 AND 3176 AND level BETWEEN 12 AND 103)<>35*92 THEN
  RAISE EXCEPTION 'trial monster baseline must cover all candidates 12–103';
 END IF;
END $$;
UPDATE game_trial_rules SET max_level=100 WHERE id=1 AND max_level=60;
 VALUES('progression-v5',100,80,'4d768109ae6d3d4852c14580dee319766ecec9138b7d4c244a50fe48d3f4fe0a','f68e9dc5a171d6491614a101ff28af1896339c668d987a94f1410578fca6317a','trial-v5-need-per-anchor-unit')
 ON CONFLICT(version) DO NOTHING;
DO $$ BEGIN
 IF NOT EXISTS(SELECT FROM game_progression_versions WHERE version='progression-v5' AND player_cap=100 AND pet_cap=80 AND player_checksum='4d768109ae6d3d4852c14580dee319766ecec9138b7d4c244a50fe48d3f4fe0a' AND pet_checksum='f68e9dc5a171d6491614a101ff28af1896339c668d987a94f1410578fca6317a' AND reward_version='trial-v5-need-per-anchor-unit') THEN
  RAISE EXCEPTION 'progression version conflicts with existing manifest';
 END IF;
END $$;
